// Part 11 lesson 3 solution: an NCO and a complex mixer (digital down-conversion step).
module nco_mixer #(
    parameter int AW = 16,
    parameter int LA = 8,
    parameter int XW = 12
) (
    input  logic                 clk,
    input  logic                 rst_n,
    input  logic                 en,
    input  logic [AW-1:0]        fw,
    input  logic signed [XW-1:0] x,
    output logic                 out_valid,
    output logic signed [XW-1:0] i_out,
    output logic signed [XW-1:0] q_out
);
    localparam int CW = 16;
    logic signed [CW-1:0] lut [2**LA];
    logic [AW-1:0] acc;

    initial begin
        for (int i = 0; i < 2**LA; i++)
            lut[i] = CW'($rtoi($floor(16383.0 * $sin(6.283185307179586 * i / (2.0**LA)) + 0.5)));
    end

    wire [AW-1:0] acc_next = en ? acc + fw : acc;
    wire [LA-1:0] next_idx = acc_next[AW-1 -: LA];

    // Prefetch the table values for the phase that will be current next cycle.
    // This moves the table lookup off the multiply-to-output path without
    // changing the sample-to-output latency.
    logic signed [CW-1:0] s_prefetch, c_prefetch;
    logic signed [CW-1:0] s_pipe, c_pipe;
    logic signed [XW-1:0] x_pipe;
    logic valid_pipe;

    wire signed [XW+CW-1:0] pi = x_pipe * c_pipe;
    wire signed [XW+CW-1:0] pq = x_pipe * (-s_pipe);

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            acc        <= '0;
            s_prefetch <= lut[0];
            c_prefetch <= lut[LA'(2**(LA-2))];
            valid_pipe <= 1'b0;
            s_pipe     <= '0;
            c_pipe     <= '0;
            x_pipe     <= '0;
            out_valid  <= 1'b0;
            i_out      <= '0;
            q_out      <= '0;
        end else begin
            acc        <= acc_next;
            s_prefetch <= lut[next_idx];
            c_prefetch <= lut[next_idx + LA'(2**(LA-2))];

            valid_pipe <= en;
            if (en) begin
                s_pipe <= s_prefetch;
                c_pipe <= c_prefetch;
                x_pipe <= x;
            end

            out_valid <= valid_pipe;
            if (valid_pipe) begin
                i_out <= XW'(pi >>> 14);
                q_out <= XW'(pq >>> 14);
            end
        end
    end
endmodule
