// Part 11 lesson 3 solution: an NCO and a complex mixer (digital down-conversion step).
module nco_mixer #(
    parameter int AW = 16,
    parameter int LA = 8,
    parameter int XW = 12
) (
    input  logic                 clk,
    input  logic                 rst_n,
    input  logic                 en,
    input  logic [AW-1:0]        fw,
    input  logic signed [XW-1:0] x,
    output logic                 out_valid,
    output logic signed [XW-1:0] i_out,
    output logic signed [XW-1:0] q_out
);
    localparam int CW = 16;
    localparam int PW = XW + CW;
    localparam int LO_W = XW + 9;
    localparam int HI_W = XW + 8;

    logic signed [CW-1:0] lut [2**LA];
    logic [AW-1:0] acc;

    logic signed [XW-1:0] stage_x;
    logic signed [CW-1:0] stage_c;
    logic signed [CW-1:0] stage_neg_s;

    logic signed [LO_W-1:0] i_lo_reg, q_lo_reg;
    logic signed [HI_W-1:0] i_hi_reg, q_hi_reg;
    logic valid_stage;

    initial begin
        for (int i = 0; i < 2**LA; i++)
            lut[i] = CW'($rtoi($floor(16383.0 * $sin(6.283185307179586 * i / (2.0**LA)) + 0.5)));
    end

    wire [LA-1:0] idx = acc[AW-1 -: LA];
    wire signed [CW-1:0] s = lut[idx];
    wire signed [CW-1:0] c = lut[idx + LA'(2**(LA-2))];

    wire signed [LO_W-1:0] i_lo_comb =
        stage_x * $signed({1'b0, stage_c[7:0]});
    wire signed [HI_W-1:0] i_hi_comb =
        stage_x * $signed(stage_c[CW-1:8]);
    wire signed [LO_W-1:0] q_lo_comb =
        stage_x * $signed({1'b0, stage_neg_s[7:0]});
    wire signed [HI_W-1:0] q_hi_comb =
        stage_x * $signed(stage_neg_s[CW-1:8]);

    wire signed [PW-1:0] pi_stage =
        {{(PW-LO_W){i_lo_reg[LO_W-1]}}, i_lo_reg}
        + {i_hi_reg, 8'b0};
    wire signed [PW-1:0] pq_stage =
        {{(PW-LO_W){q_lo_reg[LO_W-1]}}, q_lo_reg}
        + {q_hi_reg, 8'b0};

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            acc         <= '0;
            stage_x     <= '0;
            stage_c     <= '0;
            stage_neg_s <= '0;
            i_lo_reg    <= '0;
            i_hi_reg    <= '0;
            q_lo_reg    <= '0;
            q_hi_reg    <= '0;
            valid_stage <= 1'b0;
            out_valid   <= 1'b0;
        end else begin
            valid_stage <= en;
            out_valid   <= valid_stage;

            if (en) begin
                acc         <= acc + fw;
                stage_x     <= x;
                stage_c     <= c;
                stage_neg_s <= -s;
            end

            if (valid_stage) begin
                i_lo_reg <= i_lo_comb;
                i_hi_reg <= i_hi_comb;
                q_lo_reg <= q_lo_comb;
                q_hi_reg <= q_hi_comb;
            end
        end
    end

    always_comb begin
        i_out = XW'(pi_stage >>> 14);
        q_out = XW'(pq_stage >>> 14);
    end
endmodule
